'use strict';

const bcrypt = require('bcrypt');

// Teachers are a User -> Employee -> Teacher chain (each FK NOT NULL/UNIQUE),
// so this single seeder walks all three steps in order rather than being
// split across three files - the later steps can't run without the ids
// generated by the earlier ones.
module.exports = {
  async up(queryInterface, Sequelize) {
    const [teacherRole] = await queryInterface.sequelize.query(
      `SELECT role_id FROM roles WHERE role_name = 'Teacher';`,
      { type: Sequelize.QueryTypes.SELECT }
    );

    const departments = await queryInterface.sequelize.query(`SELECT department_id, department_name FROM departments;`, {
      type: Sequelize.QueryTypes.SELECT,
    });
    const deptId = (name) => departments.find((d) => d.department_name === name).department_id;

    const desired = [
      {
        email: 'imran.sheikh@aims.edu.pk',
        employee_code: 'EMP-001',
        first_name: 'Imran',
        last_name: 'Sheikh',
        department_name: 'Computer Science',
        designation: 'Assistant Professor',
        specialization: 'Programming & Algorithms',
      },
      {
        email: 'farah.yousuf@aims.edu.pk',
        employee_code: 'EMP-002',
        first_name: 'Farah',
        last_name: 'Yousuf',
        department_name: 'Computer Science',
        designation: 'Lecturer',
        specialization: 'Software Systems',
      },
      {
        email: 'kashif.naeem@aims.edu.pk',
        employee_code: 'EMP-003',
        first_name: 'Kashif',
        last_name: 'Naeem',
        department_name: 'Electrical Engineering',
        designation: 'Lecturer',
        specialization: 'Circuit Design',
      },
      {
        email: 'sana.riaz@aims.edu.pk',
        employee_code: 'EMP-004',
        first_name: 'Sana',
        last_name: 'Riaz',
        department_name: 'Electrical Engineering',
        designation: 'Assistant Professor',
        specialization: 'Digital Systems',
      },
      {
        email: 'waqas.ali@aims.edu.pk',
        employee_code: 'EMP-005',
        first_name: 'Waqas',
        last_name: 'Ali',
        department_name: 'Software Engineering',
        designation: 'Lecturer',
        specialization: 'Software Engineering Practices',
      },
      {
        email: 'mehak.fatima@aims.edu.pk',
        employee_code: 'EMP-006',
        first_name: 'Mehak',
        last_name: 'Fatima',
        department_name: 'Software Engineering',
        designation: 'Assistant Professor',
        specialization: 'Requirements & Design',
      },
    ];

    const existingEmployees = await queryInterface.sequelize.query(`SELECT employee_code FROM employees;`, {
      type: Sequelize.QueryTypes.SELECT,
    });
    const existingCodes = existingEmployees.map((e) => e.employee_code);
    const toCreate = desired.filter((t) => !existingCodes.includes(t.employee_code));

    if (toCreate.length === 0) return;

    // CHANGE THIS PASSWORD immediately after first login in any real deployment.
    const hashedPassword = await bcrypt.hash('Teach@123', 10);

    await queryInterface.bulkInsert(
      'users',
      toCreate.map((t) => ({
        email: t.email,
        password_hash: hashedPassword,
        role_id: teacherRole.role_id,
        is_active: true,
        email_verified: true,
        failed_login_attempts: 0,
        created_at: new Date(),
        updated_at: new Date(),
      })),
      { ignoreDuplicates: true } // email is UNIQUE
    );

    const users = await queryInterface.sequelize.query(
      `SELECT user_id, email FROM users WHERE email IN (:emails);`,
      { replacements: { emails: toCreate.map((t) => t.email) }, type: Sequelize.QueryTypes.SELECT }
    );
    const userId = (email) => users.find((u) => u.email === email).user_id;

    await queryInterface.bulkInsert(
      'employees',
      toCreate.map((t) => ({
        user_id: userId(t.email),
        employee_code: t.employee_code,
        first_name: t.first_name,
        last_name: t.last_name,
        department_id: deptId(t.department_name),
        designation: t.designation,
        basic_salary: 120000.0,
        hire_date: '2022-08-01',
        employment_status: 'Active',
        is_deleted: false,
      })),
      { ignoreDuplicates: true } // employee_code is UNIQUE
    );

    const employees = await queryInterface.sequelize.query(
      `SELECT employee_id, employee_code FROM employees WHERE employee_code IN (:codes);`,
      { replacements: { codes: toCreate.map((t) => t.employee_code) }, type: Sequelize.QueryTypes.SELECT }
    );
    const employeeId = (code) => employees.find((e) => e.employee_code === code).employee_id;

    await queryInterface.bulkInsert(
      'teachers',
      toCreate.map((t) => ({
        employee_id: employeeId(t.employee_code),
        specialization: t.specialization,
        is_deleted: false,
      })),
      { ignoreDuplicates: true } // employee_id is UNIQUE
    );
  },
  async down(queryInterface) {
    const codes = ['EMP-001', 'EMP-002', 'EMP-003', 'EMP-004', 'EMP-005', 'EMP-006'];
    const emails = [
      'imran.sheikh@aims.edu.pk',
      'farah.yousuf@aims.edu.pk',
      'kashif.naeem@aims.edu.pk',
      'sana.riaz@aims.edu.pk',
      'waqas.ali@aims.edu.pk',
      'mehak.fatima@aims.edu.pk',
    ];
    // teachers/employees cascade away via employees->users FK ON DELETE CASCADE,
    // but delete explicitly in dependency order for clarity and to avoid
    // relying on cascade when running this seeder's down in isolation.
    await queryInterface.sequelize.query(
      `DELETE t FROM teachers t JOIN employees e ON t.employee_id = e.employee_id WHERE e.employee_code IN (:codes);`,
      { replacements: { codes } }
    );
    await queryInterface.bulkDelete('employees', { employee_code: codes });
    await queryInterface.bulkDelete('users', { email: emails });
  },
};
